    function ciktiSahnesi(){const alan=document.createElement('div');alan.dataset.fdFiyatCikti='true';alan.style.cssText='position:fixed;left:-16000px;top:0;width:1120px;background:#fff;pointer-events:none;';document.body.appendChild(alan);return alan}
