    function firmaArayuzunuUygula(){const app=document.getElementById('insaatFiyatApp');if(!app)return;const aciklama=app.querySelector('.fd-ft-head p');if(aciklama)aciklama.textContent='Firmayı seçin; o firmaya verdiğiniz güncel fiyatları ve tarihli fiyat sayfalarını yönetin.';const yanBaslik=app.querySelector('.fd-ft-sidebar-title strong'),yanAciklama=app.querySelector('.fd-ft-sidebar-head small'),yanArama=app.querySelector('.fd-ft-sidebar-head input');if(yanBaslik)yanBaslik.textContent='Firmalar';if(yanAciklama)yanAciklama.textContent='Firma adına göre arayın';if(yanArama)yanArama.placeholder='Firma ara';app.querySelector('.fd-ft-head .fd-ft-actions button[onclick="fdFiyatV2DosyaFormuAc()"]')?.remove();const yanYeni=app.querySelector('.fd-ft-sidebar-add button');if(yanYeni)yanYeni.textContent='+ Yeni Firma';const duzenle=document.getElementById('fdFtDosyaDuzenleBtn'),zam=document.getElementById('fdFtYeniSayfaBtn');if(duzenle)duzenle.textContent='Firma Bilgisi';if(zam){zam.textContent='Fiyat Güncelle';zam.setAttribute('onclick','fdFiyatV2ZamYap()')}const ad=document.getElementById('fdFtDosyaAd'),tur=document.getElementById('fdFtDosyaTur'),firma=document.getElementById('fdFtDosyaFirma'),modal=document.getElementById('fdFtDosyaModal');ad?.closest('.form-group')?.remove();tur?.closest('.form-group')?.remove();if(firma){firma.required=true;const grup=firma.closest('.form-group');if(grup){grup.style.gridColumn='1/-1';const etiket=grup.querySelector('label');if(etiket)etiket.textContent='Firma adı'}}if(modal){const baslik=modal.querySelector('.modal-header h3'),kaydet=modal.querySelector('button[type="submit"]');if(baslik)baslik.textContent='Yeni Firma';if(kaydet)kaydet.textContent='Firmayı Kaydet'}}
    function modulAdiniGuncelle(){const m=VARSAYILAN_ANA_MENU_MODULLERI.find(x=>x.anahtar===MODUL);if(m){m.ad='Fiyat ve Teklifler';m.aciklama='Firmalara göre güncel fiyatlar, tarihli sayfalar ve ürün geçmişi';m.ikon='💼'}if(fdUygulamaSekmeTanimlari?.[MODUL]){fdUygulamaSekmeTanimlari[MODUL].ad='Fiyat ve Teklifler';fdUygulamaSekmeTanimlari[MODUL].ikon='💼'}anaMenuModulKartlariniUygula?.();const kart=document.querySelector('#appHub .workspace-launcher [data-ana-menu-modul="'+MODUL+'"]');if(kart){const ikon=kart.querySelector('.workspace-card-icon'),ad=kart.querySelector('strong'),aciklama=kart.querySelector('small');if(ikon)ikon.textContent='💼';if(ad)ad.textContent='Fiyat ve Teklifler';if(aciklama)aciklama.textContent='Firmalara göre güncel ve geçmiş fiyatlar'}}
